#include <iostream>
using namespace std;

int main() {
    const int META = 1000;
    int pontos = 0;
    cout << "Pontos da fase: ";
    cin >> pontos;

    if (pontos >= META) {
        cout << "Fase concluída!" << endl;
    } else {
        cout << "Ainda não foi desta vez." << endl;
        cout << "Faltaram " << META - pontos << " pontos." << endl;
    }
    cout << "Fim da fase." << endl;
    return 0;
}

