cpp3m2.solucao:
#include <iostream>
using namespace std;

int main() {
    int mes = 0;
    int ano = 0;
    cout << "Mês (1 a 12): ";
    cin >> mes;
    cout << "Ano: ";
    cin >> ano;

    bool bissexto = (ano % 4 == 0 && ano % 100 != 0) || ano % 400 == 0;

    if (mes < 1 || mes > 12) {
        cout << "Mês inválido." << endl;
    } else {
        int dias = 31;
        if (mes == 2 && bissexto) {
            dias = 29;
        } else if (mes == 2) {
            dias = 28;
        } else if (mes == 4 || mes == 6 || mes == 9 || mes == 11) {
            dias = 30;
        }
        cout << "O mês " << mes << " de " << ano << " tem " << dias << " dias." << endl;
    }
    return 0;
}

