cpp3m3.solucao:
#include <iostream>
using namespace std;

int main() {
    int x = 10;
    int y = 4;
    char comando = ' ';
    int passos = 0;

    cout << "Comando (w/a/s/d): ";
    cin >> comando;
    cout << "Passos: ";
    cin >> passos;

    bool valido = true;
    switch (comando) {
        case 'w':
        case 'W':
            y += passos;
            break;
        case 's':
        case 'S':
            y -= passos;
            break;
        case 'd':
        case 'D':
            x += passos;
            break;
        case 'a':
        case 'A':
            x -= passos;
            break;
        default:
            valido = false;
    }

    if (valido) {
        cout << "O herói foi de (10, 4) para (" << x << ", " << y << ")." << endl;
    } else {
        cout << "Comando inválido: o herói ficou em (" << x << ", " << y << ")." << endl;
    }
    return 0;
}

