#include <iostream>
#include <iomanip>
#include <string>
using namespace std;

int main() {
    const double TAXA_POR_KG = 4.50;
    const double TAXA_EXPRESSA = 20.00;
    const double MINIMO_FRETE_GRATIS = 250.00;

    int regiao = 0;
    double peso = 0;
    double compra = 0;
    char resposta = ' ';

    cout << "Região (1 a 5): ";
    cin >> regiao;
    cout << "Peso (kg): ";
    cin >> peso;
    cout << "Valor da compra (R$): ";
    cin >> compra;
    cout << "Entrega expressa (s/n): ";
    cin >> resposta;

    string nome;
    double base = 0;
    switch (regiao) {
        case 1: nome = "Sudeste"; base = 15.00; break;
        case 2: nome = "Sul"; base = 18.00; break;
        case 3: nome = "Centro-Oeste"; base = 22.00; break;
        case 4: nome = "Nordeste"; base = 25.00; break;
        case 5: nome = "Norte"; base = 30.00; break;
        default:
            cout << "Região inválida." << endl;
            return 0;  // encerra o programa aqui
    }

    double adicional = peso > 1 ? (peso - 1) * TAXA_POR_KG : 0;
    bool expressa = resposta == 's' || resposta == 'S';
    double taxa = expressa ? TAXA_EXPRESSA : 0;
    bool gratis = compra >= MINIMO_FRETE_GRATIS && !expressa && (regiao == 1 || regiao == 2);
    double total = gratis ? 0 : base + adicional + taxa;

    cout << fixed << setprecision(2);
    cout << "Frete para " << nome << endl;
    cout << "Base: R$ " << base << endl;
    cout << "Adicional de peso: R$ " << adicional << endl;
    cout << "Taxa expressa: R$ " << taxa << endl;
    cout << "Total: R$ " << total << (gratis ? " (frete grátis)" : "") << endl;
    return 0;
}
